"""The benchmark corpus: committed hashes, generated bytes.

bench/corpus/SHA256SUMS is committed — the trust anchor, and the only corpus
file in git. The bytes themselves generate on demand into the gitignored
bench/corpus-gen/ (the generator is bench/zig/corpus.zig, `just corpus`).
This module verifies the generated tree against the committed hashes before
any run uses it and hands the raw-file hashes to the runner, the manifest,
and the per-round parser (every arm's meta record carries the hashes it
actually read on the box).
"""

import hashlib
from dataclasses import dataclass
from pathlib import Path

ANCHOR = Path("bench") / "corpus" / "SHA256SUMS"
GENERATED = Path("bench") / "corpus-gen"


@dataclass(frozen=True)
class Corpus:
    dir: Path
    # The raw files, name to SHA-256 hex (derived from the anchor: the
    # anchor names the set; a corpus revision grows it by appending rows).
    hashes: dict[str, str]
    # The committed SHA256SUMS text (the trust anchor).
    sums: str
    # One hash over every verified file (names and digests, sorted): the
    # corpus's identity in the manifest, without the bytes.
    tree_sha256: str


def tree_hash(recorded: dict[str, str]) -> str:
    """One hash over the verified anchor: name and digest per file, sorted."""
    digest = hashlib.sha256()
    for name in sorted(recorded):
        digest.update(f"{name}  {recorded[name]}\n".encode())
    return digest.hexdigest()


def load(root: Path) -> Corpus:
    """Verify the generated corpus against the committed SHA256SUMS."""
    anchor = root / ANCHOR
    if not anchor.is_file():
        raise ValueError(f"{anchor}: committed trust anchor missing")
    sums = anchor.read_text()
    recorded = {}
    for line in sums.splitlines():
        digest, name = line.split("  ", 1)
        recorded[name] = digest
    if not recorded:
        raise ValueError(f"{anchor}: empty SHA256SUMS")
    directory = root / GENERATED
    if not directory.is_dir():
        raise ValueError(f"{directory}: generated corpus missing; run `just corpus`")
    for name, digest in sorted(recorded.items()):
        path = directory / name
        if not path.is_file():
            raise ValueError(f"{path}: generated corpus file missing; run `just corpus`")
        actual = hashlib.sha256(path.read_bytes()).hexdigest()
        if actual != digest:
            raise ValueError(f"{path}: generated bytes disagree with {anchor}")
    # The raw files are the anchor rows without an extension (the reference
    # blobs all carry one); the anchor defines the set, so a corpus revision
    # is an anchor edit and a regeneration, never a harness change.
    raw = {name: digest for name, digest in recorded.items() if "." not in name}
    if not raw:
        raise ValueError(f"{anchor}: no raw corpus files")
    return Corpus(directory, raw, sums, tree_hash(recorded))
